// A run's shadow gained `scale` and `anchor` for shapes after pages were
// first stored with the four original fields; both read as their defaults
// when absent, so an older page with a shadow still decodes.
extension CharShadow {
    enum CodingKeys: String, CodingKey { case color, dx, dy, blur, scale, anchor }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        self.init(color: try c.decode(Color.self, forKey: .color), dx: try c.decode(Double.self, forKey: .dx),
                  dy: try c.decode(Double.self, forKey: .dy), blur: try c.decode(Double.self, forKey: .blur))
        scale = try c.decodeIfPresent(Double.self, forKey: .scale) ?? scale
        anchor = try c.decodeIfPresent(Offset.self, forKey: .anchor) ?? anchor
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        try c.encode(color, forKey: .color)
        try c.encode(dx, forKey: .dx)
        try c.encode(dy, forKey: .dy)
        try c.encode(blur, forKey: .blur)
        if scale != 1 { try c.encode(scale, forKey: .scale) }
        if anchor != Offset(0.5, 0.5) { try c.encode(anchor, forKey: .anchor) }
    }
}
